     "ex": "from html.parser import HTMLParser\n\nclass PriceParser(HTMLParser):\n    def __init__(self):\n        super().__init__(); self.in_price = False; self.prices = []\n    def handle_starttag(self, tag, attrs):\n        self.in_price = (\"class\", \"price_color\") in attrs\n    def handle_data(self, data):\n        if self.in_price and data.strip():\n            self.prices.append(data.strip()); self.in_price = False\n\nhtml = '<p class=\"price_color\">£51.77</p><p class=\"price_color\">£ —</p><p class=\"price_color\">£13.99</p>'\np = PriceParser(); p.feed(html)\nfor raw in p.prices:\n    try:\n        print(\"ok\", float(raw.lstrip(\"£ \")))\n    except ValueError:\n        print(\"quarantine\", repr(raw))",
